package io.github.testlens.migration.tooling;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static io.github.testlens.migration.tooling.MigrationGitIsolationAction.*;

/** Fixed-template Git mutation boundary. It exposes no arbitrary Git argument API and performs no network action. */
public final class MigrationGitIsolationService {
    enum MutationOperation{VERIFY_COMMIT,BRANCH_EXISTS,CREATE_BRANCH,WORKTREE_ADD,STASH_REF,STASH_CREATE_TRACKED,STASH_CREATE_UNTRACKED,STASH_APPLY}
    private final String executable;private final MigrationGitService readOnly;private final GitProcessRunner runner=new GitProcessRunner();
    public MigrationGitIsolationService(){this("git");}
    public MigrationGitIsolationService(String trustedGitExecutable){executable=trustedExecutable(trustedGitExecutable);readOnly=new MigrationGitService(trustedGitExecutable);}

    public Result createBranch(MigrationGitService.Result before,MigrationCheckpoint checkpoint,MigrationStateStore store,String branch,String exactBaseCommit,MigrationAuthorization authorization)throws IOException{long start=System.nanoTime();if(!authorization.allows(MigrationAuthorization.Capability.CREATE_BRANCH))return stop(Operation.CREATE_BRANCH,checkpoint,Reason.APPROVAL_REQUIRED,start);Reason pre=precondition(before,checkpoint);if(pre!=null)return stop(Operation.CREATE_BRANCH,checkpoint,pre,start);if(!before.preflight().ongoingOperations().isEmpty())return stop(Operation.CREATE_BRANCH,checkpoint,Reason.ONGOING_GIT_OPERATION,start);if(!readOnly.validBranchCandidate(before.localContext().worktreeRoot(),branch))return stop(Operation.CREATE_BRANCH,checkpoint,Reason.INVALID_BRANCH,start);MigrationGitIsolationAction.oid(exactBaseCommit);if(!success(run(MutationOperation.VERIFY_COMMIT,before.localContext().worktreeRoot(),exactBaseCommit,null)))return stop(Operation.CREATE_BRANCH,checkpoint,Reason.BASE_REF_CHANGED,start);if(success(run(MutationOperation.BRANCH_EXISTS,before.localContext().worktreeRoot(),branch,null)))return stop(Operation.CREATE_BRANCH,checkpoint,Reason.BRANCH_ALREADY_EXISTS,start);GitProcessRunner.Result command=run(MutationOperation.CREATE_BRANCH,before.localContext().worktreeRoot(),branch,exactBaseCommit);return finish(Operation.CREATE_BRANCH,before,checkpoint,store,command,branch,exactBaseCommit,null,null,start);
    }

    public Result createWorktree(MigrationGitService.Result before,MigrationCheckpoint checkpoint,MigrationStateStore store,Path trustedDestination,String branch,String exactBaseCommit,MigrationAuthorization authorization)throws IOException{long start=System.nanoTime();if(!authorization.allows(MigrationAuthorization.Capability.CREATE_WORKTREE)||!authorization.allows(MigrationAuthorization.Capability.CREATE_BRANCH))return stop(Operation.CREATE_WORKTREE,checkpoint,Reason.APPROVAL_REQUIRED,start);if(!authorization.allows(MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS))return stop(Operation.CREATE_WORKTREE,checkpoint,Reason.REPOSITORY_HELPER_APPROVAL_REQUIRED,start);Reason pre=precondition(before,checkpoint);if(pre!=null)return stop(Operation.CREATE_WORKTREE,checkpoint,pre,start);if(!before.preflight().ongoingOperations().isEmpty())return stop(Operation.CREATE_WORKTREE,checkpoint,Reason.ONGOING_GIT_OPERATION,start);if(!readOnly.validBranchCandidate(before.localContext().worktreeRoot(),branch))return stop(Operation.CREATE_WORKTREE,checkpoint,Reason.INVALID_BRANCH,start);MigrationGitIsolationAction.oid(exactBaseCommit);if(!success(run(MutationOperation.VERIFY_COMMIT,before.localContext().worktreeRoot(),exactBaseCommit,null)))return stop(Operation.CREATE_WORKTREE,checkpoint,Reason.BASE_REF_CHANGED,start);if(success(run(MutationOperation.BRANCH_EXISTS,before.localContext().worktreeRoot(),branch,null)))return stop(Operation.CREATE_WORKTREE,checkpoint,Reason.BRANCH_ALREADY_EXISTS,start);Path destination=trustedDestination.toAbsolutePath().normalize();if(destination.equals(before.localContext().worktreeRoot())||Files.exists(destination,LinkOption.NOFOLLOW_LINKS))return stop(Operation.CREATE_WORKTREE,checkpoint,Reason.WORKTREE_DESTINATION_EXISTS,start);GitProcessRunner.Result command=run(MutationOperation.WORKTREE_ADD,before.localContext().worktreeRoot(),destination.toString(),branch+"\0"+exactBaseCommit);MigrationGitService.Result observed=readOnly.inspect(destination);if(command.exitCode()!=0||observed.localContext()==null){List<Reason>reasons=observed.localContext()==null?List.of(Reason.GIT_COMMAND_FAILED):List.of(Reason.PARTIAL_STATE_OBSERVED);return new Result(Operation.CREATE_WORKTREE,observed.localContext()==null?Status.FAILED:Status.PARTIAL,reasons,checkpoint.checkpointId(),null,branch,exactBaseCommit,observed.preflight().worktreeBindingRef(),null,elapsed(start),List.of("No automatic worktree removal is attempted"));}if(!exactBaseCommit.equals(observed.preflight().head().commit())||!branch.equals(observed.preflight().head().branch())||!before.preflight().repositoryBindingRef().equals(observed.preflight().repositoryBindingRef()))return new Result(Operation.CREATE_WORKTREE,Status.PARTIAL,List.of(Reason.PARTIAL_STATE_OBSERVED),checkpoint.checkpointId(),null,branch,exactBaseCommit,observed.preflight().worktreeBindingRef(),null,elapsed(start),List.of("Created worktree identity did not match; manual review required"));MigrationCheckpoint after=fresh(observed,checkpoint,store,Operation.CREATE_WORKTREE.name(),branch,exactBaseCommit,observed.preflight().worktreeBindingRef());return new Result(Operation.CREATE_WORKTREE,Status.APPLIED,List.of(),checkpoint.checkpointId(),after.checkpointId(),branch,exactBaseCommit,observed.preflight().worktreeBindingRef(),null,elapsed(start),List.of("Repository checkout helpers were explicitly authorized"));}

    public Result createStash(MigrationGitService.Result before,MigrationCheckpoint checkpoint,MigrationStateStore store,StashScope scope,MigrationAuthorization authorization)throws IOException{long start=System.nanoTime();if(!authorization.allows(MigrationAuthorization.Capability.CREATE_STASH))return stop(Operation.CREATE_STASH,checkpoint,Reason.APPROVAL_REQUIRED,start);if(!authorization.allows(MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS))return stop(Operation.CREATE_STASH,checkpoint,Reason.REPOSITORY_HELPER_APPROVAL_REQUIRED,start);Reason pre=precondition(before,checkpoint);if(pre!=null)return stop(Operation.CREATE_STASH,checkpoint,pre,start);if(!before.preflight().ongoingOperations().isEmpty())return stop(Operation.CREATE_STASH,checkpoint,Reason.ONGOING_GIT_OPERATION,start);String old=optionalOid(run(MutationOperation.STASH_REF,before.localContext().worktreeRoot(),null,null));GitProcessRunner.Result command=run(scope==StashScope.TRACKED_ONLY?MutationOperation.STASH_CREATE_TRACKED:MutationOperation.STASH_CREATE_UNTRACKED,before.localContext().worktreeRoot(),null,null);String oid=optionalOid(run(MutationOperation.STASH_REF,before.localContext().worktreeRoot(),null,null));if(command.exitCode()!=0||oid==null||oid.equals(old))return stop(Operation.CREATE_STASH,checkpoint,Reason.STASH_NOT_CREATED,start);MigrationGitService.Result observed=readOnly.inspect(before.localContext().worktreeRoot());MigrationCheckpoint after=fresh(observed,checkpoint,store,Operation.CREATE_STASH.name(),oid,scope.name());StashRecord stash=new StashRecord(oid,scope,before.preflight().repositoryBindingRef(),before.preflight().worktreeBindingRef(),checkpoint.checkpointId(),after.checkpointId(),before.sourceState().sourceStateDigest(),observed.sourceState().sourceStateDigest());return new Result(Operation.CREATE_STASH,Status.APPLIED,List.of(),checkpoint.checkpointId(),after.checkpointId(),null,null,observed.preflight().worktreeBindingRef(),stash,elapsed(start),List.of("Exact stash OID retained; stash is not dropped"));}

    public Result restoreStash(MigrationGitService.Result before,MigrationCheckpoint checkpoint,MigrationStateStore store,StashRecord stash,MigrationAuthorization authorization)throws IOException{long start=System.nanoTime();if(!authorization.allows(MigrationAuthorization.Capability.RESTORE_STASH))return stop(Operation.RESTORE_STASH,checkpoint,Reason.APPROVAL_REQUIRED,start);if(!authorization.allows(MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS))return stop(Operation.RESTORE_STASH,checkpoint,Reason.REPOSITORY_HELPER_APPROVAL_REQUIRED,start);Reason pre=precondition(before,checkpoint);if(pre!=null)return stop(Operation.RESTORE_STASH,checkpoint,pre,start);if(!stash.repositoryBindingRef().equals(before.preflight().repositoryBindingRef())||!stash.worktreeBindingRef().equals(before.preflight().worktreeBindingRef())||!stash.postStashSourceDigest().equals(before.sourceState().sourceStateDigest()))return stop(Operation.RESTORE_STASH,checkpoint,Reason.STASH_RESTORE_PRECONDITION_FAILED,start);GitProcessRunner.Result command=run(MutationOperation.STASH_APPLY,before.localContext().worktreeRoot(),stash.stashOid(),null);MigrationGitService.Result observed=readOnly.inspect(before.localContext().worktreeRoot());MigrationCheckpoint after=fresh(observed,checkpoint,store,Operation.RESTORE_STASH.name(),stash.stashOid());if(command.exitCode()!=0)return new Result(Operation.RESTORE_STASH,Status.PARTIAL,List.of(Reason.STASH_RESTORE_CONFLICT),checkpoint.checkpointId(),after.checkpointId(),null,null,observed.preflight().worktreeBindingRef(),stash,elapsed(start),List.of("Stash was not dropped; conflicts were not reset or cleaned"));return new Result(Operation.RESTORE_STASH,Status.APPLIED,List.of(),checkpoint.checkpointId(),after.checkpointId(),null,null,observed.preflight().worktreeBindingRef(),stash,elapsed(start),List.of("Exact stash OID applied with --index and retained"));}

    private GitProcessRunner.Result run(MutationOperation operation,Path cwd,String value,String second)throws IOException{List<String>args=switch(operation){case VERIFY_COMMIT->List.of("rev-parse","--verify",MigrationGitIsolationAction.oid(value)+"^{commit}");case BRANCH_EXISTS->List.of("show-ref","--verify","--quiet","refs/heads/"+branch(value));case CREATE_BRANCH->List.of("branch","--",branch(value),MigrationGitIsolationAction.oid(second));case WORKTREE_ADD->{int split=second.indexOf('\0');yield List.of("worktree","add","-b",branch(second.substring(0,split)),"--",value,MigrationGitIsolationAction.oid(second.substring(split+1)));}case STASH_REF->List.of("rev-parse","--verify","refs/stash");case STASH_CREATE_TRACKED->List.of("stash","push","--message","test-lens-migration-v1");case STASH_CREATE_UNTRACKED->List.of("stash","push","--include-untracked","--message","test-lens-migration-v1");case STASH_APPLY->List.of("stash","apply","--index",MigrationGitIsolationAction.oid(value));};List<String>command=new ArrayList<>(List.of(executable,"-c","core.fsmonitor=false","-c","color.ui=false","--no-pager"));command.addAll(args);return runner.run(command,cwd,mutationEnvironment(),Duration.ofMinutes(2),32*1024*1024);}
    static Map<String,String>mutationEnvironment(){return Map.of("GIT_TERMINAL_PROMPT","0","GIT_PAGER","cat","PAGER","cat","LC_ALL","C");}
    private Result finish(Operation op,MigrationGitService.Result before,MigrationCheckpoint checkpoint,MigrationStateStore store,GitProcessRunner.Result command,String branch,String base,String worktree,StashRecord stash,long start)throws IOException{MigrationGitService.Result observed=readOnly.inspect(before.localContext().worktreeRoot());if(!success(command))return new Result(op,Status.FAILED,List.of(reason(command)),checkpoint.checkpointId(),null,branch,base,worktree,stash,elapsed(start),List.of("Observed repository state was refreshed after failure"));MigrationCheckpoint after=fresh(observed,checkpoint,store,op.name(),branch,base);return new Result(op,Status.APPLIED,List.of(),checkpoint.checkpointId(),after.checkpointId(),branch,base,worktree,stash,elapsed(start),List.of());}
    private static MigrationCheckpoint fresh(MigrationGitService.Result observed,MigrationCheckpoint before,MigrationStateStore store,String...actionFields)throws IOException{String digest="migration-isolation-action-v1:sha256:"+MigrationDigests.digest("migration-isolation-action-v1",actionFields);List<MigrationArtifactRef>refs=new ArrayList<>(before.artifacts());refs.add(new MigrationArtifactRef(MigrationArtifactRef.Type.ISOLATION_ACTION,1,digest,"isolation-actions/"+digest.substring(digest.lastIndexOf(':')+1),MigrationArtifactRef.Completeness.COMPLETE));MigrationCheckpoint after=MigrationCheckpoint.create(observed.preflight(),observed.sourceState(),before.configuration(),refs,before.proposalSetRef(),before.decisionsRef());store.write(after);return after;}
    private static Reason precondition(MigrationGitService.Result before,MigrationCheckpoint checkpoint){if(before.localContext()==null||!checkpoint.repositoryBindingRef().equals(before.preflight().repositoryBindingRef()))return Reason.REPOSITORY_BINDING_CHANGED;if(!checkpoint.worktreeBindingRef().equals(before.preflight().worktreeBindingRef()))return Reason.WORKTREE_BINDING_CHANGED;return null;}
    private static Result stop(Operation op,MigrationCheckpoint cp,Reason reason,long start){Status status=reason==Reason.APPROVAL_REQUIRED||reason==Reason.REPOSITORY_HELPER_APPROVAL_REQUIRED?Status.SAFE_STOP:Status.PRECONDITION_FAILED;return new Result(op,status,List.of(reason),cp.checkpointId(),null,null,null,null,null,elapsed(start),List.of());}
    private static boolean success(GitProcessRunner.Result r){return !r.timedOut()&&!r.interrupted()&&!r.outputTruncated()&&r.exitCode()==0;}
    private static Reason reason(GitProcessRunner.Result r){return r.timedOut()?Reason.GIT_TIMEOUT:r.outputTruncated()?Reason.GIT_OUTPUT_LIMIT:Reason.GIT_COMMAND_FAILED;}
    private static String optionalOid(GitProcessRunner.Result r){if(!success(r))return null;String v=new String(r.stdout(),StandardCharsets.UTF_8).strip().toLowerCase();return v.matches("[0-9a-f]{40}|[0-9a-f]{64}")?v:null;}
    private static String branch(String value){if(value==null||value.isBlank()||value.length()>512||value.startsWith("-")||value.indexOf('\0')>=0)throw new IllegalArgumentException("branch");return value;}
    private static String trustedExecutable(String value){if(value==null||value.isBlank()||"git".equals(value))return"git";Path p=Path.of(value);if(!p.isAbsolute()||!Files.isRegularFile(p))throw new IllegalArgumentException("trusted Git executable");return p.normalize().toString();}
    private static Duration elapsed(long start){return Duration.ofNanos(System.nanoTime()-start);}
}
